repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$repo_root"
umask 077
# Preserve trailing newlines until validation; ordinary command substitution
# would strip them and accept a malformed multi-line value as its prefix.
value="$(
  if [[ "$key" == "SLACK_MEMBER_CHANNEL_ALLOWED_IDS" ]]; then
    # Validate the original input before Bash can discard NUL bytes. Reuse the
    # deployment validator with only this value, without reading host settings.
    python3 -c 'import runpy, sys; value = sys.stdin.read(); runpy.run_path("scripts/validate_message_sync_deploy_config.py")["validate"]({"SLACK_MEMBER_CHANNEL_ALLOWED_IDS": value}); sys.stdout.write(value)' || exit $?
  else
    cat
  fi
  printf '\037'
)"
value="${value%$'\037'}"

if [[ "$value" == *$'\n'* || "$value" == *$'\r'* ]]; then
  echo "Invalid single-line payload for ${key}" >&2
  exit 1
fi

case "$key" in
  VALLEY_MCP_UNIFIED_ALIAS_ENABLED)
    printf '%s' "$value" | python3 scripts/validate_valley_mcp_deploy_config.py --stdin "$key"
    ;;
  MLAI_MCP_NATIVE_AGENTS_ENABLED|AGENT_RUNTIME_ENABLED|AGENT_RUNTIME_NATIVE_ENABLED|AGENT_RUNTIME_NATIVE_REPLIES_ENABLED|AGENT_RUNTIME_MCP_EVENTS_ENABLED|AGENT_RUNTIME_NATIVE_COMMUNITIES|AGENT_RUNTIME_DOT_SETUP_URL|AGENT_RUNTIME_NATIVE_PERSONAL_LIMIT|AGENT_RUNTIME_COMMUNITY_ENABLED|AGENT_RUNTIME_PERSONAL_CONTEXT_ENABLED|AGENT_RUNTIME_NATIVE_ALWAYS_ADMIT|AGENT_RUNTIME_NATIVE_QUEUE_TTL_MINUTES|AGENT_RUNTIME_NATIVE_ADMISSION_DAILY_CAP|AGENT_RUNTIME_NATIVE_LIMIT_TIMEZONE|AGENT_RUNTIME_NATIVE_BACKLOG_REPLAY|AGENT_RUNTIME_MCP_EVENTS_LEASE_POLICY|AGENT_RUNTIME_NATIVE_DURABLE_WATCH|AGENT_RUNTIME_NATIVE_GUEST_REPLY_ENABLED|AGENT_RUNTIME_NATIVE_DENIAL_GRACE_SECONDS|AGENT_RUNTIME_NATIVE_UNIFIED_GRACE_SECONDS|AGENT_RUNTIME_NATIVE_RENEWAL_ENABLED|MLAI_MCP_AGENT_GRANT_EXTENSION_ENABLED|MLAI_MCP_REFRESH_REPLAY_GRACE_SECONDS)
